arguments.command:
cat /workspace/input/cases.json | python3 -c "import json,sys; data=json.load(sys.stdin); print(json.dumps({k:v for k,v in data.items() if 'IC-009' in k}, indent=2))" 2>/dev/null || python3 -c "
import json
with open('/workspace/input/cases.json') as f:
    data = json.load(f)
if isinstance(data, list):
    item = [d for d in data if str(d.get('id','')) == 'IC-009']
    if item: print(json.dumps(item[0], indent=2))
else:
    ic009 = data.get('IC-009', {})
    if not ic009:
        for k in data:
            if 'IC-009' in str(k):
                ic009 = data[k]
                break
    print(json.dumps(ic009, indent=2))
"

python3 -c "
import json
with open('/workspace/input/cases.json') as f:
    data = json.load(f)
cases = data.get('cases', [])
if isinstance(cases, dict):
    for k,v in cases.items():
        if 'IC-009' in str(k):
            print(json.dumps(v, indent=2))
            break
elif isinstance(cases, list):
    for c in cases:
        if isinstance(c, str) and 'IC-009' in c:
            print('String id:', c)
            continue
        if isinstance(c, dict) and 'IC-009' in str(c.get('id','')):
            print(json.dumps(c, indent=2))
            break
"
